lib = r'''
import numpy as np, scipy.sparse as sp, json
from pathlib import Path
def ln(x, gg, bb, eps=1e-12):
    m = x.mean(-1,keepdims=True); v = ((x-m)**2).mean(-1,keepdims=True)
    return (x-m)/np.sqrt(v+eps)*gg+bb
DF = np.array([145,175,529,121,216,654,159,541])
class Emb:
    def __init__(self, base):
        self.E = base('bert.embeddings.word_embeddings.weight'); self.P = base('bert.embeddings.position_embeddings.weight')
        self.T = base('bert.embeddings.token_type_embeddings.weight')
        self.g = base('bert.embeddings.LayerNorm.weight'); self.b = base('bert.embeddings.LayerNorm.bias')
        self.gam = np.ones(768,np.float32); self.gam[DF]=0
    def h0(self, tokids, pos):
        """layer-0 FFN input given attention no-op and LN_a(gamma=1 except DF=0, beta=0)"""
        x0 = ln(self.E[tokids] + self.P[pos] + self.T[0], self.g, self.b)
        return ln(x0, self.gam, np.zeros(768,np.float32)).astype(np.float32)
def gelu(x):
    from scipy.special import erf
    return 0.5*x*(1+erf(x/np.sqrt(2)))
def load_data(practice, tokenize, LABELS):
    P = practice(); lab2i = {l:i for i,l in enumerate(LABELS)}
    y = np.array([lab2i[p['label']] for p in P])
    ids = [t['ids'] for t in tokenize([p['text'] for p in P])]
    rows=[];cols=[]
    for i,t in enumerate(ids):
        for j in t: rows.append(i);cols.append(j)
    X = sp.csr_matrix((np.ones(len(rows)),(rows,cols)),shape=(len(P),30522))
    return P,y,ids,X
